mapper.select:
SELECT r.user_id AS userId, u.user_name AS userName, NULL AS userEmpNo, u.dept_name AS userDept, COUNT(*) AS submitCount, COUNT(DISTINCT COALESCE(t.dispatch_id, t.id)) AS periodCount, MAX(r.submit_time) AS lastSubmitTime FROM flow_form_record r LEFT JOIN aut_user u ON r.user_id = u.yyyt_id LEFT JOIN flow_task t ON r.task_id = t.id LEFT JOIN flow_task_dispatch d ON COALESCE(t.dispatch_id, t.id) = d.id WHERE r.record_status = 1 AND d.task_id = #{taskId}
AND (u.user_name LIKE CONCAT('%', #{name}, '%') OR u.yyyt_id LIKE CONCAT('%', #{name}, '%'))
GROUP BY r.user_id, u.user_name, u.dept_name ORDER BY submitCount DESC, r.user_id ASC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM ( SELECT r.user_id FROM flow_form_record r LEFT JOIN aut_user u ON r.user_id = u.yyyt_id LEFT JOIN flow_task t ON r.task_id = t.id LEFT JOIN flow_task_dispatch d ON COALESCE(t.dispatch_id, t.id) = d.id WHERE r.record_status = 1 AND d.task_id = #{taskId}
AND (u.user_name LIKE CONCAT('%', #{name}, '%') OR u.yyyt_id LIKE CONCAT('%', #{name}, '%'))
GROUP BY r.user_id ) p

SELECT COUNT(*)
FROM flow_task_node tn
INNER JOIN flow_task t ON tn.task_id = t.id
LEFT JOIN flow_task_dispatch d ON t.dispatch_id = d.id
WHERE tn.task_id IN (
    SELECT DISTINCT x.task_id
    FROM flow_task_node x
    WHERE x.handler_user_id = #{userId}
)
AND d.task_id = #{taskId}



        SELECT DATE_FORMAT(submit_time, '%Y-%m') AS date, COUNT(*) AS count
        FROM flow_form_record
        WHERE record_status = 1

            AND DATE(submit_time) >= #{startDate}


            AND DATE(submit_time) <= #{endDate}

        GROUP BY DATE_FORMAT(submit_time, '%Y-%m')


        SELECT CONCAT(YEAR(submit_time), '-Q', QUARTER(submit_time)) AS date, COUNT(*) AS count
        FROM flow_form_record
        WHERE record_status = 1

            AND DATE(submit_time) >= #{startDate}


            AND DATE(submit_time) <= #{endDate}

        GROUP BY CONCAT(YEAR(submit_time), '-Q', QUARTER(submit_time))


        SELECT DATE_FORMAT(submit_time, '%Y') AS date, COUNT(*) AS count
        FROM flow_form_record
        WHERE record_status = 1

            AND DATE(submit_time) >= #{startDate}


            AND DATE(submit_time) <= #{endDate}

        GROUP BY DATE_FORMAT(submit_time, '%Y')


        SELECT DATE_FORMAT(submit_time, '%Y-%m-%d') AS date, COUNT(*) AS count
        FROM flow_form_record
        WHERE record_status = 1

            AND DATE(submit_time) >= #{startDate}


            AND DATE(submit_time) <= #{endDate}

        GROUP BY DATE_FORMAT(submit_time, '%Y-%m-%d')


ORDER BY date

