SELECT  AS date, COUNT(*) AS count
FROM flow_form_record r
INNER JOIN aut_user u ON u.yyyt_id = r.user_id
WHERE r.record_status = 1
  AND u.dept_id = #{deptId}

    AND DATE(r.submit_time) >= #{startDate}


    AND DATE(r.submit_time) <= #{endDate}

GROUP BY 
